// Run: npm pack @matrix-org/matrix-sdk-crypto-wasm@18.9.0 && tar xzf *.tgz
//      node gen_ecies.cjs ./package/node.cjs > ecies_vectors.json
//
// Generates MSC4108 ECIES vectors. Device S (the phone) is vodozemac through
// matrix-sdk-crypto-wasm. Device G (the new device) is node:crypto, written
// from the vodozemac source; vodozemac must decrypt what G writes.
const crypto = require('node:crypto');
const sdk = require(process.argv[2]);
const b64 = (b) => Buffer.from(b).toString('base64').replace(/=+$/, '');
const unb64 = (s) => Buffer.from(s, 'base64');

(async () => {
  await sdk.initAsync();
  const { publicKey, privateKey } = crypto.generateKeyPairSync('x25519');
  const gPriv = unb64(privateKey.export({ format: 'jwk' }).d.replace(/-/g, '+').replace(/_/g, '/'));
  const gPub = unb64(publicKey.export({ format: 'jwk' }).x.replace(/-/g, '+').replace(/_/g, '/'));

  const s = new sdk.Ecies();
  const out = s.establish_outbound_channel(new sdk.Curve25519PublicKey(b64(gPub)), 'MATRIX_QR_CODE_LOGIN_INITIATE');
  const sChan = out.channel;
  const initial = out.initial_message;
  const sPub = unb64(initial.split('|')[1]);

  // G side in node:crypto.
  const sKeyObj = crypto.createPublicKey({ key: { kty: 'OKP', crv: 'X25519', x: b64(sPub).replace(/\+/g, '-').replace(/\//g, '_') }, format: 'jwk' });
  const shared = crypto.diffieHellman({ privateKey, publicKey: sKeyObj });
  const suffix = `|${b64(gPub)}|${b64(sPub)}`;
  const kdf = (name, len) => Buffer.from(crypto.hkdfSync('sha512', shared, Buffer.alloc(0), 'MATRIX_QR_CODE_LOGIN' + name + suffix, len));
  const gEnc = kdf('_ENCKEY_G', 32);
  const nonce = (n) => { const b = Buffer.alloc(12); b.writeBigUInt64LE(BigInt(n)); return b; };
  const gSeal = (pt, n) => { const c = crypto.createCipheriv('chacha20-poly1305', gEnc, nonce(n), { authTagLength: 16 }); return b64(Buffer.concat([c.update(pt), c.final(), c.getAuthTag()])); };

  const vec = {
    source: 'S: @matrix-org/matrix-sdk-crypto-wasm 18.9.0 (vodozemac). G: node:crypto ' + process.version + '. Generated by bipe-beeper scripts, ' + new Date().toISOString().slice(0, 10) + '.',
    g_private_key: b64(gPriv),
    g_public_key: b64(gPub),
    s_public_key: b64(sPub),
    initial_message: initial,
    check_code: sChan.check_code().to_digit(),
    check_code_bytes: b64(sChan.check_code().as_bytes()),
    s_to_g: [],
    g_to_s: [],
  };
  // G nonce 0 is the LOGIN_OK reply.
  const gMsgs = ['MATRIX_QR_CODE_LOGIN_OK', JSON.stringify({ type: 'm.login.protocol', protocol: 'device_authorization_grant', device_authorization_grant: { verification_uri: 'https://account.example.org/link' }, device_id: 'ABCDEFGHIJ' }), JSON.stringify({ type: 'm.login.success' })];
  const sMsgs = [JSON.stringify({ type: 'm.login.protocols', protocols: ['device_authorization_grant'], homeserver: 'https://matrix.example.org/' }), JSON.stringify({ type: 'm.login.protocol_accepted' }), JSON.stringify({ type: 'm.login.secrets', cross_signing: { master_key: 'rTtSv67XGS6k/rg6/yTG/m573cyFTPFRqluFhQY+hSw', self_signing_key: '4jbPt7jh5D2iyM4U+3IDa+WthgJB87IQN1ATdkau+xk', user_signing_key: 'YkFKtkjcsTxF6UAzIIG/l6Nog/G2RigCRfWj3cjNWeM' }, backup: { algorithm: 'm.megolm_backup.v1.curve25519-aes-sha2', backup_version: '2', key: 'AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA' } })];
  for (let i = 0; i < gMsgs.length; i++) {
    const ct = gSeal(Buffer.from(gMsgs[i]), i);
    const pt = sChan.decrypt(ct); // throws if vodozemac rejects it
    if (pt !== gMsgs[i]) throw new Error('vodozemac decrypted a different plaintext');
    vec.g_to_s.push({ plaintext: gMsgs[i], ciphertext: ct });
    if (i < sMsgs.length) vec.s_to_g.push({ plaintext: sMsgs[i], ciphertext: sChan.encrypt(sMsgs[i]) });
  }
  console.log(JSON.stringify(vec, null, 2));
})().catch((e) => { console.error(e); process.exit(1); });
